class Solution {
  public List<Integer> minimumFlips(int n, int[][] edges, String start, String target) {
    int[] head = new int[n], next = new int[2 * (n - 1)], to = new int[2 * (n - 1)];
    java.util.Arrays.fill(head, -1);
    int cnt = 0;
    for (int i = 0; i < n - 1; i++) {
      to[cnt] = edges[i][1];
      next[cnt] = head[edges[i][0]];
      head[edges[i][0]] = cnt++;
      to[cnt] = edges[i][0];
      next[cnt] = head[edges[i][1]];
      head[edges[i][1]] = cnt++;
    }
    int[] parity = new int[n], par = new int[n], parEdge = new int[n], order = new int[n];
    int total = 0;
    for (int i = 0; i < n; i++) {
      parity[i] = start.charAt(i) != target.charAt(i) ? 1 : 0;
      total ^= parity[i];
    }
    if (total == 1) return new ArrayList<>(java.util.Arrays.asList(-1));
    par[0] = -1;
    int qh = 0, qt = 0;
    order[qt++] = 0;
    while (qh < qt) {
      int u = order[qh++];
      for (int e = head[u]; e >= 0; e = next[e]) {
        int v = to[e];
        if (v == par[u]) continue;
        par[v] = u;
        parEdge[v] = e / 2;
        order[qt++] = v;
      }
    }
    List<Integer> res = new ArrayList<>();
    for (int idx = n - 1; idx > 0; idx--) {
      int v = order[idx];
      if (parity[v] == 1) {
        res.add(parEdge[v]);
        parity[par[v]] ^= 1;
      }
    }
    java.util.Collections.sort(res);
    return res;
  }
}
